'use client';
import clsx from "clsx";
import Link from "next/link";
import { useMemo } from "react";

type Props = {
    readonly href: string;
    readonly arialLabel?: string;
    readonly type?: 'primary' | 'secondary';
    readonly children: React.ReactNode;
}

const LinkHome: React.FC<Props> = ({
    href,
    arialLabel,
    type,
    children
}) => {

    const style = useMemo(() => {
        switch (type) {
            case 'primary':
                return 'text-white bg-blue-500 hover:bg-blue-700';
            case 'secondary':
                return 'text-gray-700 bg-gray-200 hover:bg-gray-400';
            default:
                return '';
        }

    }, [type])

    return (
        <div className="w-full flex justify-center items-center mt-8">
            <Link href={href} aria-label={arialLabel} className={clsx('', style)}>
                {children}
            </Link>
        </div>
    )
}

export default LinkHome;